import java.lang.instrument.Instrumentation;
import java.lang.reflect.Field;
import java.lang.management.ManagementFactory;
public final class LayoutProbe {
 private static Instrumentation instrumentation;
 public static void premain(String arguments, Instrumentation value) { instrumentation=value; }
 public static void main(String[] arguments) throws Exception {
  com.sun.management.HotSpotDiagnosticMXBean vm=ManagementFactory.getPlatformMXBean(com.sun.management.HotSpotDiagnosticMXBean.class);
  for(String name:new String[]{"UseCompressedOops","UseCompressedClassPointers","ObjectAlignmentInBytes"}) System.out.println(name+"="+vm.getVMOption(name).getValue());
  Field field=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");field.setAccessible(true);
  sun.misc.Unsafe unsafe=(sun.misc.Unsafe)field.get(null);
  for(String name:arguments) {
   Object instance=unsafe.allocateInstance(Class.forName(name));
   System.out.println(name+"="+instrumentation.getObjectSize(instance));
  }
 }
}
